def get_unused_imports(filepath):
    ''''''Find unused imports in a Python file''''''
    try:
        with open(filepath, ''r'', encoding=''utf-8'') as f:
            content = f.read()
        tree = ast.parse(content)
    except:
        return []

    # Collect all imported names
    imported_names = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.asname if alias.asname else alias.name
                imported_names[name] = (node.lineno, alias.name)
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                if alias.name == ''*'':
                    continue
                name = alias.asname if alias.asname else alias.name
                imported_names[name] = (node.lineno, f''{node.module}.{alias.name}'')

    # Collect all used names
    used_names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            used_names.add(node.id)
        elif isinstance(node, ast.Attribute):
            # Get the root name
            n = node
            while isinstance(n, ast.Attribute):
                n = n.value
            if isinstance(n, ast.Name):
                used_names.add(n.id)

    # Find unused
    unused = []
    for name, (lineno, full_import) in imported_names.items():
        if name not in used_names:
            unused.append((lineno, name, full_import))

    return unused

total_unused = 0
